struct Landing {
    study_piece::Piece piece;
    int distance = 0;
};

inline std::optional<Landing> project(const study_grid::Grid& board,
                                      const study_piece::Piece& start) noexcept {
    // Only a cleanly placed piece may be projected. This rejects shapes that
    // leave the board and shapes overlapping filled cells.
    if (study_collision::classify(board, start) !=
        study_collision::Placement::clear) {
        return std::nullopt;
    }

    // A clear start already blocked below will return distance zero.
    Landing landing{start, 0};
    study_piece::Piece cursor = start;  // private copy; `start` stays const

    for (int step = 0; step < study_grid::Grid::kRows; ++step) {
        const study_movement::Result result =
            study_gravity::try_down(board, cursor);
        if (result == study_movement::Result::moved) {
            landing.piece = cursor;  // try_down commits only on success
            ++landing.distance;
            continue;
        }
        if (result == study_movement::Result::blocked) {
            return landing;  // obstacle reached: report the last valid landing
        }
        return std::nullopt;  // invalid: fail closed, change nothing
    }

    // Budget exhausted without a blocked result: fail closed rather than guess.
    return std::nullopt;
}

// Derived value, not another owner of game state. No clock or queue advances.
std::optional<study_ghost::Landing> ghost() const noexcept {
    return active_ ? study_ghost::project(board_, *active_) : std::nullopt;
}

if (!study_board_scene::render(gl,empty_program.name(),filled_program.name(),
        vertex_array.name(),vertex_buffer.vertex_count(),mesh.empty_vertices,*layout)) return 1;
if (ghost && !study_piece_view::render(gl,ghost_program.name(),ghost_array.name(),
                                       ghost_buffer.vertex_count())) return 1;
if (round.active() && !study_piece_view::render(gl,piece_program.name(),piece_array.name(),
                              piece_buffer.vertex_count())) return 1;

auto ghost = round.ghost();
if (round.active() && !ghost) return 1;
study_gl::VertexBuffer ghost_buffer(gl);
study_gl::VertexArray ghost_array(gl);
study_gl::Program ghost_program(gl);
if (!study_board_scene::link_program(gl,ghost_program,study_ghost_view::fragment)) return 1;
if (ghost) {
    const auto cells=study_piece::to_board(ghost->piece);
    if (!cells) return 1;
    const auto hint=study_piece_view::make_visible_mesh(*cells);
    if (!ghost_buffer.upload(hint.vertices.data(),hint.count) ||
        !ghost_array.configure(ghost_buffer.name())) return 1;
}

// Recompute after the batch: board/pose can both change on a lock.
if (piece_changed) {
    ghost = round.ghost();
    if (round.active() && !ghost) return 1;
    if (ghost) {
        const auto cells=study_piece::to_board(ghost->piece);
        if (!cells) return 1;
        const auto hint=study_piece_view::make_visible_mesh(*cells);
        if (!ghost_buffer.replace_same_size(hint.vertices.data(),hint.count)) return 1;
    }
}
